{
  "items": [
    {
      "name": "Polynomial.wronskian",
      "module_name": "Mathlib.RingTheory.Polynomial.Wronskian",
      "kind": "definition",
      "type": "{R : Type u_1} → [inst : CommRing R] → Polynomial R → Polynomial R → Polynomial R"
    },
    {
      "name": "IsCoprime.wronskian_eq_zero_iff",
      "module_name": "Mathlib.RingTheory.Polynomial.Wronskian",
      "kind": "theorem",
      "type": "∀ {R : Type u_1} [inst : CommRing R] [NoZeroDivisors R] {a b : Polynomial R},\n  IsCoprime a b → (a.wronskian b = 0 ↔ Polynomial.derivative a = 0 ∧ Polynomial.derivative b = 0)"
    },
    {
      "name": "Polynomial.natDegree_wronskian_lt_add",
      "module_name": "Mathlib.RingTheory.Polynomial.Wronskian",
      "kind": "theorem",
      "type": "∀ {R : Type u_1} [inst : CommRing R] {a b : Polynomial R},\n  a.wronskian b ≠ 0 → (a.wronskian b).natDegree < a.natDegree + b.natDegree"
    },
    {
      "name": "Polynomial.wronskian_add_left",
      "module_name": "Mathlib.RingTheory.Polynomial.Wronskian",
      "kind": "theorem",
      "type": "∀ {R : Type u_1} [inst : CommRing R] (a b c : Polynomial R), (a + b).wronskian c = a.wronskian c + b.wronskian c"
    },
    {
      "name": "Polynomial.wronskian_zero_left",
      "module_name": "Mathlib.RingTheory.Polynomial.Wronskian",
      "kind": "theorem",
      "type": "∀ {R : Type u_1} [inst : CommRing R] (a : Polynomial R), Polynomial.wronskian 0 a = 0"
    },
    {
      "name": "Polynomial.wronskian_self_eq_zero",
      "module_name": "Mathlib.RingTheory.Polynomial.Wronskian",
      "kind": "theorem",
      "type": "∀ {R : Type u_1} [inst : CommRing R] (a : Polynomial R), a.wronskian a = 0"
    },
    {
      "name": "Polynomial.wronskian_zero_right",
      "module_name": "Mathlib.RingTheory.Polynomial.Wronskian",
      "kind": "theorem",
      "type": "∀ {R : Type u_1} [inst : CommRing R] (a : Polynomial R), a.wronskian 0 = 0"
    },
    {
      "name": "Polynomial.wronskianBilin_apply",
      "module_name": "Mathlib.RingTheory.Polynomial.Wronskian",
      "kind": "theorem",
      "type": "∀ {R : Type u_1} [inst : CommRing R] (a b : Polynomial R), ((Polynomial.wronskianBilin R) a) b = a.wronskian b"
    }
  ]
}
